-- Funder and partner-organisation scholarships open to Ghanaians (not tied to one school), UK, US, Australia and Ghana only, from the funders' own pages, checked 14 Nov 2026. Not verified. Skips ones already held by name.
insert into scholarships (name, funder, country, funding_type, level, criteria, deadline, link, source_url, award_note, school_id, verified, demo)
select v.name, v.funder, v.country, v.funding_type, v.level, v.criteria, v.deadline, v.link, v.link, v.award_note, null, false, false
from (values
($q$Chevening Scholarships (Ghana)$q$,$q$UK Foreign, Commonwealth and Development Office (FCDO) and partner organisations$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$Open to Ghanaians. Needs at least two years (2,800 hours) of work experience, an undergraduate degree that qualifies for a UK master's, and one-year taught master's courses. You must return to Ghana after study.$q$,NULL::date,$q$https://www.chevening.org/scholarship/ghana/$q$,$q$UK government funded one-year master's (applications for 2027-28 closed; check for next round)$q$),
($q$Commonwealth Distance Learning Master's Scholarships$q$,$q$Commonwealth Scholarship Commission (CSC)$q$,$q$United Kingdom$q$,$q$Partial$q$,$q$Postgraduate$q$,$q$For citizens of eligible developing Commonwealth countries including Ghana, living there. Needs at least a 2:1 degree and inability to afford the course. You apply with a participating UK university for a modular distance learning master's.$q$,NULL::date,$q$https://cscuk.fcdo.gov.uk/scholarships/commonwealth-distance-learning-scholarships-candidates/$q$,$q$Tuition fees and study grants where needed$q$),
($q$Commonwealth Professional Fellowships$q$,$q$Commonwealth Scholarship Commission (CSC)$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$For mid-career professionals from eligible Commonwealth countries including Ghana, with at least five years of relevant work experience and a current employer to return to. A short professional placement at a UK host organisation, not a degree.$q$,NULL::date,$q$https://cscuk.fcdo.gov.uk/scholarships/commonwealth-professional-fellowships-information-for-candidates$q$,$q$Return airfare, monthly stipend, arrival allowance, visa fee and study costs$q$),
($q$Gates Cambridge Scholarship$q$,$q$Gates Cambridge Trust$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$Open to citizens of any country outside the UK, including Ghana. For full-time PhD, MLitt and selected one-year postgraduate courses at the University of Cambridge. Looks for academic excellence and potential for social leadership. Partner schools: University of Cambridge.$q$,NULL::date,$q$https://gatescambridge.org/apply/eligibility$q$,$q$Full cost scholarship for postgraduate study at Cambridge$q$),
($q$Rhodes Scholarships for West Africa$q$,$q$Rhodes Trust$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$Ghana is in the West Africa constituency. Postgraduate study at the University of Oxford. Eligibility and selection are set by the constituency, so read the Information for Candidates. Partner schools: University of Oxford.$q$,NULL::date,$q$https://www.rhodeshouse.ox.ac.uk/scholarships/apply/west-africa$q$,$q$Postgraduate study at Oxford (check Conditions of Tenure for what is covered)$q$),
($q$Clarendon Fund Scholarships$q$,$q$University of Oxford (Clarendon Fund)$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$No nationality restriction. New full-time or part-time master's or DPhil applicants at Oxford are considered automatically when they apply by the December or January deadline. All subjects. Partner schools: University of Oxford.$q$,NULL::date,$q$https://www.ox.ac.uk/admissions/graduate/fees-and-funding/funding/clarendon/applicants$q$,$q$Full course fees plus living grant (at least GBP 20,780 for 2025-26)$q$),
($q$Rotary Peace Fellowships (University of Bradford)$q$,$q$Rotary Foundation$q$,$q$United Kingdom$q$,$q$Full$q$,$q$Postgraduate$q$,$q$For people with a bachelor's degree, at least three years of relevant peace or development work, and strong English. Master's fellows study at the Rotary Peace Centre at the University of Bradford in the UK, not in their home country. Partner schools: University of Bradford.$q$,NULL::date,$q$https://www.rotary.org/en/our-programs/peace-fellowships-masters-degree-programs$q$,$q$Funded master's study in peace and development$q$),
($q$GREAT Scholarships for Ghana$q$,$q$British Council and UK universities (GREAT Britain campaign)$q$,$q$United Kingdom$q$,$q$Partial$q$,$q$Postgraduate$q$,$q$For Ghanaian passport holders living in Ghana with an undergraduate degree. For a one-year taught postgraduate course at a participating UK university. Deadlines differ by university. Partner schools: Anglia Ruskin University, Birmingham Newman University, Durham University, Edge Hill University, Imperial College London, Kingston University London, Lancaster University, Liverpool Hope University, Royal Holloway, University of London, University of Edinburgh, University of Manchester, University of Dundee.$q$,NULL::date,$q$https://study-uk.britishcouncil.org/scholarships/great-scholarships/ghana$q$,$q$GBP 10,000 towards tuition fees$q$),
